'use strict';
let extractionController=null,mixFade=null,mixFrame=0,musicDuck=1;
function musicTargetVolume(){return Math.max(0,Math.min(1,(state.settings.musicVolume??35)/100))*musicDuck;}
function smoothMix(now){cancelAnimationFrame(mixFrame);if(!playback.running)return;if(mixFade&&!playback.paused){const dt=Math.max(0,Math.min(150,now-mixFade.last));mixFade.last=now;mixFade.elapsed+=dt;const p=Math.min(1,mixFade.elapsed/mixFade.duration);if(playback.audio)playback.audio.volume=Math.sin(p*Math.PI/2)*musicTargetVolume();if(playback.fadingAudio)playback.fadingAudio.volume=Math.cos(p*Math.PI/2)*mixFade.fromVolume;if(p>=1){playback.fadingAudio?.pause();playback.fadingAudio=null;mixFade=null;}}else if(mixFade)mixFade.last=now;else if(playback.audio&&!playback.paused){const target=musicTargetVolume();playback.audio.volume+= (target-playback.audio.volume)*.06;}mixFrame=requestAnimationFrame(smoothMix);}
let musicGeneration=0;
async function setMusic(tid){
 if(playback.audioTrip===tid)return;
 const generation=++musicGeneration,t=tripById(tid),m=locationMusic(t);let next=null;
 if(m?.confirmed&&(m.audioId||m.url)){
  const url=await locationMusicURL(t);if(generation!==musicGeneration||!playback.running)return;
  if(url){next=new Audio(url);next.preload='auto';next.loop=true;next.volume=0;
   try{await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('音频载入超时')),12000);const done=fn=>{clearTimeout(timer);next.oncanplay=null;next.onerror=null;fn();};next.oncanplay=()=>done(resolve);next.onerror=()=>done(()=>reject(Error('音频载入失败')));next.load();});
    if(m.start&&m.start<next.duration)next.currentTime=m.start;
    if(generation!==musicGeneration||!playback.running){next.pause();return;}
    if(!playback.paused)await next.play();
   }catch(e){next.pause();if(generation===musicGeneration)toast('配乐未能播放，原配乐继续；可暂停后重试。');return;}
  }
 }
 if(generation!==musicGeneration||!playback.running){next?.pause();return;}
 playback.fadingAudio?.pause();playback.fadingAudio=playback.audio;playback.audio=next;playback.audioTrip=tid;
 const seconds=Math.max(1,Math.min(8,+state.settings.musicFadeSeconds||3));mixFade={elapsed:0,last:performance.now(),duration:seconds*1000,fromVolume:playback.fadingAudio?.volume||0};
 cancelAnimationFrame(mixFrame);mixFrame=requestAnimationFrame(smoothMix);
}
function setMusicDuck(duck){musicDuck=duck?.23:1;}
function stopMusicMix(){musicGeneration++;showFilmMusicCredit(null);cancelAnimationFrame(mixFrame);playback.fadingAudio?.pause();playback.fadingAudio=null;mixFade=null;}
function openMusic(tid){showDialog('地点音乐',`<div class="music-settings"><label>城市间淡入淡出 <strong id="music-fade-value">${state.settings.musicFadeSeconds||3}</strong> 秒<input id="music-fade" type="range" min="1" max="8" value="${state.settings.musicFadeSeconds||3}"></label><label>背景音乐音量 <strong id="music-volume-value">${state.settings.musicVolume??35}</strong>%<input id="music-volume" type="range" min="0" max="80" value="${state.settings.musicVolume??35}"></label></div><audio id="city-music-player" aria-label="城市配乐试听" controls hidden style="width:100%;margin:12px 0"></audio><p>支持本地音频文件，或从视频提取音频。音乐仅用于对应地点；城市切换时交叉淡化，旅行视频原声播放时自动压低配乐。</p>${state.trips.map(t=>{const m=locationMusic(t);return `<div class="music-row" id="music-${esc(t.id)}"><div><h3>${esc(t.cn||t.name)}</h3><p>${(m.audioId||m.url)?esc(m.title||m.filename||'本地配乐'):'尚未添加音乐'}${m.fromVideo?' · 视频提取':m.url?' · '+esc(m.mood):''}</p>${(m.audioId||m.url)?`<small>${m.confirmed?'已用于放映':'待确认'}${m.duration?' · '+Math.round(m.duration)+' 秒':''}</small>`:''}</div><button data-music-upload="${esc(t.id)}">${(m.audioId||m.url)?'更换文件':'本地上传'}</button>${(m.audioId||m.url)?`<button data-music-listen="${esc(t.id)}">试听</button><button data-music-detail="${esc(t.id)}">设置</button>`:''}</div>`;}).join('')}<details class="music-credits"><summary>配乐来源与署名</summary><p>Music: Kevin MacLeod (incompetech.com). Licensed under Creative Commons Attribution 4.0. 放映时循环播放、调整音量并淡入淡出。</p>${Object.values(CITY_MUSIC).map(m=>`<p><a href="${m.source}" target="_blank" rel="noopener">${esc(m.title)}</a> — Kevin MacLeod · <a href="${m.license}" target="_blank" rel="noopener">CC BY 4.0</a></p>`).join('')}<a href="/assets/music/CREDITS.txt" download>下载录屏音乐署名</a></details><div id="audio-extract-status"></div><div class="form-actions"><button class="primary-btn" id="music-done">完成</button></div>`);$('#music-fade').oninput=e=>{state.settings.musicFadeSeconds=+e.target.value;$('#music-fade-value').textContent=e.target.value;save();};$('#music-volume').oninput=e=>{state.settings.musicVolume=+e.target.value;$('#music-volume-value').textContent=e.target.value;save();};$$('[data-music-upload]').forEach(b=>b.onclick=()=>{selectedTrip=b.dataset.musicUpload;$('#music-input').click();});$$('[data-music-listen]').forEach(b=>b.onclick=async()=>{const player=$('#city-music-player');if(!player.paused&&player.dataset.trip===b.dataset.musicListen){player.pause();return;}const t=tripById(b.dataset.musicListen),url=await locationMusicURL(t);if(url){musicPreview=player;player.src=url;player.dataset.trip=t.id;player.hidden=false;player.volume=(state.settings.musicVolume??35)/100;await player.play().catch(()=>toast('音频格式暂不支持。'));}});$$('[data-music-detail]').forEach(b=>b.onclick=()=>musicDetail(tripById(b.dataset.musicDetail)));$('#music-done').onclick=closeDialog;if(tid)document.getElementById('music-'+tid)?.scrollIntoView({block:'nearest'});}
function musicDetail(t){const m=locationMusic(t);showDialog((t.cn||t.name)+' · 配乐设置',`<label>曲目名称<input id="local-song-title" maxlength="150" value="${esc(m.title||m.filename||'')}"></label><label>从第几秒开始<input id="local-song-start" type="number" min="0" step=".1" value="${m.start||0}"></label><label><input id="local-song-confirmed" type="checkbox" ${m.confirmed?'checked':''}> 用作这个地点的音乐</label><div class="hint">${esc(m.filename||'')} ${m.fromVideo?'· 从视频提取的独立音频':''}</div><div class="form-actions"><button class="text-btn" id="local-music-back">返回音乐库</button><button class="primary-btn" id="save-local-song">保存</button></div>`);$('#local-music-back').onclick=()=>openMusic(t.id);$('#save-local-song').onclick=()=>{const start=+$('#local-song-start').value;if(!Number.isFinite(start)||start<0||(m.duration&&start>=m.duration)){toast('音乐起点需要在音频时长内。');return;}m.title=$('#local-song-title').value.trim();m.start=start;m.confirmed=$('#local-song-confirmed').checked;t.music={...m};save();openMusic(t.id);};}
async function audioDuration(blob){return new Promise(resolve=>{const url=URL.createObjectURL(blob),a=new Audio();const done=v=>{URL.revokeObjectURL(url);a.removeAttribute('src');resolve(v);};a.onloadedmetadata=()=>done(Number.isFinite(a.duration)?a.duration:null);a.onerror=()=>done(null);a.src=url;});}
async function extractLocalVideo(file,onProgress,controller){if(!window.MediaRecorder||!window.AudioContext)throw Error('当前浏览器无法提取视频音频，请上传单独的音频文件。');const url=URL.createObjectURL(file),video=document.createElement('video');video.src=url;video.preload='auto';video.playsInline=true;const ctx=new AudioContext();let recorder,source;await ctx.resume();try{await new Promise((resolve,reject)=>{video.onloadedmetadata=resolve;video.onerror=()=>reject(Error('此视频格式无法读取。'));controller.signal.addEventListener('abort',()=>reject(Error('已取消提取')),{once:true});});if(!Number.isFinite(video.duration)||video.duration<=0)throw Error('无法识别视频时长。');const duration=video.duration;const dest=ctx.createMediaStreamDestination();source=ctx.createMediaElementSource(video);source.connect(dest);const mime=['audio/webm;codecs=opus','audio/mp4','audio/webm'].find(t=>MediaRecorder.isTypeSupported(t));if(!mime)throw Error('当前浏览器没有可用的音频编码器。');recorder=new MediaRecorder(dest.stream,{mimeType:mime,audioBitsPerSecond:160000});const chunks=[];const result=new Promise((resolve,reject)=>{recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onerror=()=>reject(Error('音频提取失败。'));recorder.onstop=()=>resolve(new Blob(chunks,{type:mime.split(';')[0]}));});let hasAudio=false;let detector;try{detector=video.captureStream?.();}catch{}recorder.start(300);video.ontimeupdate=()=>{if((detector?.getAudioTracks().length||0)>0||video.webkitAudioDecodedByteCount>0)hasAudio=true;onProgress(Math.min(1,video.currentTime/duration));};video.onended=()=>{if(recorder.state!=='inactive')recorder.stop();};controller.signal.addEventListener('abort',()=>{video.pause();if(recorder.state!=='inactive')recorder.stop();},{once:true});await video.play();const blob=await result;if(controller.signal.aborted)throw Error('已取消提取');if(!hasAudio)throw Error('这个视频未检测到音轨，请选择有声音的视频。');return{blob,duration};}finally{video.pause();video.removeAttribute('src');video.load();source?.disconnect();await ctx.close();URL.revokeObjectURL(url);}}
$('#music-input').accept='audio/*,video/*,.mp3,.m4a,.wav,.ogg,.flac,.mp4,.mov,.webm';
$('#music-input').onchange=async e=>{const file=e.target.files[0],t=tripById(selectedTrip);e.target.value='';if(!file||!t)return;try{const isVideo=file.type.startsWith('video/')||/\.(mp4|mov|webm|mkv)$/i.test(file.name);let blob=file,duration=null;if(isVideo){extractionController=new AbortController();showDialog('从视频提取音频',`<p>${esc(file.name)}</p><p>提取在本地进行，需要将这段视频读取一遍。</p><progress id="extract-progress" max="100" value="0"></progress><div id="extract-percent" class="hint">0%</div><div class="form-actions"><button class="outline-btn" id="cancel-extract">取消提取</button></div>`);$('#cancel-extract').onclick=()=>extractionController?.abort();const result=await extractLocalVideo(file,p=>{if($('#extract-progress')){$('#extract-progress').value=p*100;$('#extract-percent').textContent=Math.round(p*100)+'%';}},extractionController);blob=result.blob;duration=result.duration;extractionController=null;}else{if(!file.type.startsWith('audio/')&&!/\.(mp3|m4a|wav|ogg|flac|aac)$/i.test(file.name))throw Error('请选择音频或视频文件。');duration=await audioDuration(file);}const id=uid();await putFile(id,blob);t.music={...t.music,audioId:id,title:file.name.replace(/\.[^.]+$/,''),filename:file.name,confirmed:true,fromVideo:isVideo,duration,start:0};save();openMusic(t.id);toast(isVideo?'音频已提取并用于这个地点。':'音乐已添加到这个地点。');}catch(e){extractionController=null;openMusic(t.id);toast(e.message||'音乐导入失败。');}};
const baseCloseDialog=closeDialog;
closeDialog=function(){extractionController?.abort();baseCloseDialog();};
// Rebind the visible close control after adding cancellation behavior.
$('#close-dialog').onclick=closeDialog;
$('#editor').addEventListener('close',()=>extractionController?.abort());
document.addEventListener('click',e=>{if(e.target.closest('#location-music-button'))openMusic(activeCity);});
const timingEditorBase=openTiming;
openTiming=function(){timingEditorBase();const section=document.createElement('div');section.className='typing-settings';section.innerHTML=`<label>文字书写速度 <strong id="type-speed-value">${(state.settings.typeSpeed||6)*2}</strong> 字 / 秒<input id="type-speed" type="range" min="4" max="24" value="${state.settings.typeSpeed||6}"></label><p class="hint">有文字的画面：最后一段文字显示完后停留 1 秒，再切换。</p>`;$('#dialog-body .form-actions').before(section);$('#type-speed').oninput=e=>{state.settings.typeSpeed=+e.target.value;$('#type-speed-value').textContent=+e.target.value*2;save();};};

function showFilmMusicCredit(){document.getElementById('film-music-credit')?.remove();}
